#include "v79-basis-recovery.hpp"

#include <cmath>
#include <iostream>
#include <limits>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>

namespace {

using solver::v79_basis::Index;
using solver::v79_basis::Input;
using solver::v79_basis::Limits;
using solver::v79_basis::Result;

struct Fixture {
  std::vector<Index> starts, rows;
  std::vector<double> values, costs, rhs, slack, dual;
  std::vector<bool> inequality;
  Input input() const { return {starts, rows, values, costs, rhs, slack, dual, inequality}; }
};

void require(bool condition, const std::string& message) {
  if (!condition) throw std::runtime_error(message);
}

void close(double actual, double expected, const std::string& message) {
  require(std::isfinite(actual) && std::abs(actual - expected) <= 1e-12 * std::max(1.0, std::abs(expected)), message);
}

void check_equations(const Fixture& fixture, const Result& result) {
  require(result.candidate_available && result.status == "candidate", "应生成候选，仍需原模型验收");
  std::vector<long double> activity(fixture.rhs.size(), 0);
  for (std::size_t col = 0; col < fixture.costs.size(); ++col) {
    long double transpose = 0;
    for (Index k = fixture.starts[col]; k < fixture.starts[col + 1]; ++k) {
      activity[fixture.rows[k]] += static_cast<long double>(fixture.values[k]) * result.x[col];
      transpose += static_cast<long double>(fixture.values[k]) * result.z[fixture.rows[k]];
    }
    close(static_cast<double>(transpose), -fixture.costs[col], "完整原矩阵对偶方程应成立");
  }
  for (std::size_t row = 0; row < fixture.rhs.size(); ++row)
    close(static_cast<double>(activity[row] + result.s[row]), fixture.rhs[row], "完整原矩阵原始方程应成立");
  if (!fixture.costs.empty()) {
    require(result.repair.candidate_available && result.repair.status == "candidate" &&
        result.repair.stats.attempts == 1, "非零维候选必须实际通过两阶段修复入口");
    require(result.repair.stats.initial_guard.complete && result.repair.stats.initial_guard.passed &&
        result.repair.stats.initial_guard.violations == 0 &&
        result.repair.stats.initial_refinement.status == "not_needed" &&
        result.repair.stats.initial_refinement.attempts == 0,
        "这些解析基应直接通过完整逐行守卫，无须额外同因子修正");
    require(result.repair.stats.direction_forward.solves <= result.repair.stats.direction_forward.attempts &&
        result.repair.stats.direction_forward.attempts <= result.repair.stats.direction_forward.systems &&
        result.repair.stats.rebuild_forward.solves <= result.repair.stats.rebuild_forward.attempts &&
        result.repair.stats.rebuild_forward.attempts <= result.repair.stats.rebuild_forward.systems,
        "每个正向右端仍至多修正一次，不要求逆更新与全LU具有相同舍入轨迹");
    require(result.repair.stats.history.initialized &&
        result.repair.stats.history.states == result.repair.stats.pivots + 1 &&
        result.repair.stats.history.swaps == result.repair.stats.pivots,
        "完整原基历史应对应实际已提交换基数");
    require(result.repair.stats.search.trials >= result.repair.stats.phase1_iterations &&
        result.repair.stats.search.non_descent + result.repair.stats.search.descent <= result.repair.stats.search.trials,
        "同基搜索仍按实际试算计账，不把已选方向等同于换基提交");
    require(result.repair.stats.eta.eta_commits + result.repair.stats.eta.full_refactor_commits ==
        result.repair.stats.pivots && result.repair.stats.eta.chain_length <= 8 &&
        result.repair.stats.eta.max_chain_length <= 8,
        "每次已提交换基须对应逆更新或真实重分解，逆更新链最多八项");
    require(result.stats.qr_analyze_calls == 0 && result.stats.qr_factor_calls == 0 &&
        result.stats.lu_analyze_calls == 1 && result.stats.lu_factor_calls == 1 &&
        result.stats.primal_solves == 1 && result.stats.dual_solves == 1 &&
        result.stats.slack_matvecs == 1, "一次选基仅用一个LU及正反各一次回代，不执行QR");
    require(result.stats.selection_pivots == static_cast<Index>(fixture.costs.size()) &&
        result.stats.rank == result.stats.selection_pivots && result.stats.qr_columns_permutation.empty() &&
        result.stats.pivot_columns.size() == fixture.costs.size(), "选择计数及主元映射完整，rank不冒称QR秩");
  }
}

Fixture dependent_priority() {
  return {{0, 2, 5}, {0, 1, 0, 1, 2}, {1, 2, 1, 2, 1}, {-1, -2}, {5, 10, 3},
      {1, 1, 1}, {1, 1, 1}, {true, true, true}};
}

Fixture identity_fixture(Index dimension) {
  Fixture f;
  f.starts.push_back(0);
  for (Index i = 0; i < dimension; ++i) {
    f.starts.push_back(i + 1); f.rows.push_back(i); f.values.push_back(1);
    f.costs.push_back(-1); f.rhs.push_back(static_cast<double>(i + 1));
    f.slack.push_back(1); f.dual.push_back(1); f.inequality.push_back(true);
  }
  return f;
}

}  // 匿名命名空间

int main() {
  try {
    int cases = 0;
    const Limits limits;
    require(limits.max_selection_work == 1000000000 && limits.max_input_nonzeros == 8000000 &&
        limits.max_factor_nonzeros == 32000000 && limits.max_dimension == 1000000 &&
        limits.max_repair_pivots == 256 && limits.max_repair_work == 200000000 &&
        limits.max_repair_factor_nonzeros == 64000000 && limits.max_eta_updates == 8,
        "初始选择和单因子额度保持不变，修复累计及逆更新额度须匹配本轮固定计划");
    {
      const Fixture f{{0, 2, 4}, {0, 1, 0, 1}, {2, 3, 1, 4}, {4, -2}, {5, 15},
          {0, 0}, {0, 0}, {false, false}};
      const auto r = solver::v79_basis::recover(f.input(), limits, {});
      check_equations(f, r);
      close(r.x[0], 1, "非对称基的第一原变量"); close(r.x[1], 3, "非对称基的第二原变量");
      close(r.z[0], -4.4, "等式允许负乘子"); close(r.z[1], 1.6, "等式对偶乘子");
      ++cases;
    }
    {
      const Fixture f{{0, 2, 4}, {0, 1, 2, 3}, {1, -1, 1, -1}, {-2, -1}, {3, 0, 4, 0},
          {1, 1, 1, 1}, {20, 1, 10, 1}, {true, true, true, true}};
      const auto r = solver::v79_basis::recover(f.input(), limits, {});
      check_equations(f, r);
      require(r.stats.selected_rows == std::vector<Index>({0, 2}), "上下界按已有比值选取");
      close(r.x[0], 3, "第一上界"); close(r.x[1], 4, "第二上界");
      close(r.s[1], 3, "第一未选下界松弛"); close(r.s[3], 4, "第二未选下界松弛");
      ++cases;
    }
    {
      const auto f = dependent_priority();
      const auto r = solver::v79_basis::recover(f.input(), limits, {});
      check_equations(f, r);
      require(r.stats.ordered_rows == std::vector<Index>({0, 1, 2}) &&
          r.stats.pivot_columns == std::vector<Index>({0, 1}) &&
          r.stats.selected_rows == std::vector<Index>({0, 2}) && r.stats.selection_rejected == 1 &&
          r.stats.selection_candidates == 3, "结构可匹配的比例依赖行须跳过，随后独立原行才能入基");
      close(r.z[1], 0, "未选行乘子应为零");
      ++cases;
    }
    {
      const Fixture f{{0, 2, 3}, {1, 2, 0}, {1, 1, 1}, {-2, -3}, {5, 4, 4},
          {1e-300, 0, 1}, {1e300, 0, 1}, {true, false, true}};
      const auto r = solver::v79_basis::recover(f.input(), limits, {});
      check_equations(f, r);
      require(r.stats.ordered_rows == std::vector<Index>({1, 0, 2}) &&
          r.stats.selected_rows == std::vector<Index>({1, 0}), "等式优先且巨大比值无需直接形成溢出的double商");
      close(r.x[0], 4, "等式恢复第一变量"); close(r.x[1], 5, "界恢复第二变量");
      ++cases;
    }
    {
      const Fixture f{{0, 2, 4}, {0, 1, 0, 1}, {1, 2, 2, 4}, {-1, -2}, {3, 6},
          {1, 1}, {1, 1}, {true, true}};
      const auto r = solver::v79_basis::recover(f.input(), limits, {});
      require(!r.candidate_available && r.status == "selection_rank_deficient" &&
          r.stats.rank == 1 && r.stats.lu_factor_calls == 0, "数值秩不足应在LU前拒绝");
      ++cases;
    }
    {
      const Fixture f{{0, 1, 1}, {0}, {1}, {1, 0}, {2, 3}, {1, 1}, {1, 1}, {true, true}};
      const auto r = solver::v79_basis::recover(f.input(), limits, {});
      require(!r.candidate_available && r.status == "structural_rank_deficient" &&
          r.stats.qr_factor_calls == 0, "结构空列应在Eigen前拒绝");
      ++cases;
    }
    {
      const Fixture f{{0, 1}, {0}, {1}, {1}, {2}, {1}, {1}, {true}};
      const auto r = solver::v79_basis::recover(f.input(), limits, {});
      require(!r.candidate_available && r.status == "repair_unavailable" &&
          r.repair.status == "no_blocker" && !r.repair.candidate_available &&
          r.stats.primal_solves == 1 && r.stats.dual_solves == 1,
          "初始负乘子无有限阻挡行时拒绝候选，不宣称原问题无界");
      ++cases;
    }
    {
      const Fixture f{{0, 2}, {0, 1}, {1, -1}, {1}, {2, 0},
          {1, 1}, {10, 1}, {true, true}};
      const auto r = solver::v79_basis::recover(f.input(), limits, {});
      check_equations(f, r);
      require(r.stats.selected_rows == std::vector<Index>({0}) &&
          r.repair.selected_rows == std::vector<Index>({1}) &&
          r.repair.stats.final_selected_rows == std::vector<Index>({1}) &&
          r.repair.stats.pivots == 1 && r.repair.stats.phase2_iterations == 1,
          "阶段二换基后初始选基账本保留，最终原行映射独立提交");
      close(r.x[0], 0, "有界问题阶段二恢复下界最优点");
      close(r.z[0], 0, "已退出基的原上界乘子为零");
      close(r.z[1], 1, "最终乘子必须映射到修复后的原下界");
      ++cases;
    }
    {
      const Fixture f{{0, 2}, {0, 1}, {1, 1}, {-1}, {2, 1},
          {1, 1}, {10, 1}, {true, true}};
      const auto r = solver::v79_basis::recover(f.input(), limits, {});
      check_equations(f, r);
      require(r.stats.selected_rows == std::vector<Index>({0}) &&
          r.repair.selected_rows == std::vector<Index>({1}) &&
          r.repair.stats.pivots == 1 && r.repair.stats.phase1_iterations == 1,
          "阶段一修复另一真实界的违反后再恢复原目标");
      close(r.x[0], 1, "阶段一到达更紧的真实上界");
      close(r.z[0], 0, "初始宽界不再承载最终乘子");
      close(r.z[1], 1, "紧界的最终乘子符号正确");
      ++cases;
    }
    {
      auto f = dependent_priority();
      f.starts = {0, 3, 2};
      const auto r = solver::v79_basis::recover(f.input(), limits, {});
      require(!r.candidate_available && r.status == "invalid_input", "坏CSC必须在访问前拒绝");
      ++cases;
    }
    {
      auto f = dependent_priority();
      f.rows[1] = f.rows[0];
      const auto r = solver::v79_basis::recover(f.input(), limits, {});
      require(!r.candidate_available && r.status == "invalid_input", "重复CSC行违反规范化输入契约");
      ++cases;
    }
    {
      auto f = dependent_priority();
      f.values[0] = std::numeric_limits<double>::infinity();
      const auto r = solver::v79_basis::recover(f.input(), limits, {});
      require(!r.candidate_available && r.status == "invalid_input", "非有限输入必须拒绝");
      ++cases;
    }
    {
      auto f = dependent_priority(); f.slack[0] = 0;
      const auto r = solver::v79_basis::recover(f.input(), limits, {});
      require(!r.candidate_available && r.status == "invalid_interior_point", "不能从非内部点形成排序比值");
      ++cases;
    }
    {
      const auto f = dependent_priority();
      Limits small = limits; small.max_input_nonzeros = 2;
      const auto r = solver::v79_basis::recover(f.input(), small, {});
      require(!r.candidate_available && r.status == "input_limit" && r.stats.qr_factor_calls == 0,
          "输入上限须在分解前生效");
      ++cases;
    }
    {
      const Fixture f{{0, 1, 2, 3}, {0, 0, 0}, {1, 1, 1}, {0, 0, 0}, {3, 0, 0},
          {1, 1, 1}, {1, 1, 1}, {true, true, true}};
      Limits small = limits; small.max_factor_nonzeros = 1;
      const auto r = solver::v79_basis::recover(f.input(), small, {});
      require(!r.candidate_available && r.status == "selection_factor_limit" && r.stats.l_nonzeros == 0 &&
          r.stats.selection_pivots == 0 && r.stats.lu_factor_calls == 0,
          "新增L列超过填充上限时必须在写任何该列填充前拒绝");
      ++cases;
    }
    {
      const auto f = identity_fixture(32);
      Result r;
      struct Expired {};
      int checks = 0;
      bool threw = false;
      try { solver::v79_basis::recover(f.input(), limits, [&] { if (++checks == 3) throw Expired{}; }, r); }
      catch (const Expired&) { threw = true; }
      require(threw && !r.candidate_available && r.status == "budget_exception" &&
          r.stats.budget_checks == 3 && r.stats.qr_factor_calls == 0, "预算异常须透传且保留未提交状态和账本");
      ++cases;
    }
    {
      const auto f = identity_fixture(32);
      Result r;
      struct Expired {};
      bool threw = false;
      try { solver::v79_basis::recover(f.input(), limits, [&] {
        if (r.stats.selection_pivots >= 1) throw Expired{};
      }, r); }
      catch (const Expired&) { threw = true; }
      require(threw && !r.candidate_available && r.status == "budget_exception" &&
          r.stats.lu_factor_calls == 0 && r.stats.selection_pivots > 0 &&
          r.stats.selection_pivots < static_cast<Index>(f.costs.size()) &&
          static_cast<Index>(r.stats.selected_rows.size()) == r.stats.selection_pivots &&
          static_cast<Index>(r.stats.pivot_columns.size()) == r.stats.selection_pivots,
          "选基预算中断必须阻止LU且保留已提交映射");
      ++cases;
    }
    {
      const auto f = dependent_priority();
      const auto full = solver::v79_basis::recover(f.input(), limits, {});
      check_equations(f, full);
      Limits boundary = limits; boundary.max_selection_work = full.stats.work_units;
      const auto exact = solver::v79_basis::recover(f.input(), boundary, {});
      check_equations(f, exact);
      --boundary.max_selection_work;
      const auto short_result = solver::v79_basis::recover(f.input(), boundary, {});
      require(!short_result.candidate_available && short_result.status == "selection_work_limit" &&
          short_result.stats.work_units == boundary.max_selection_work && short_result.stats.lu_factor_calls == 0,
          "工作额度恰好够时可完成，少一个单位必须在操作前拒绝");
      ++cases;
    }
    {
      const Fixture f{{0, 1, 2, 3}, {0, 0, 0}, {1, 1, 1}, {0, 0, 0}, {3, 0, 0},
          {1, 1, 1}, {1, 1, 1}, {true, true, true}};
      Limits boundary = limits; boundary.max_factor_nonzeros = 2;
      const auto r = solver::v79_basis::recover(f.input(), boundary, {});
      require(!r.candidate_available && r.status == "selection_rank_deficient" &&
          r.stats.l_nonzeros == 2 && r.stats.selection_pivots == 1,
          "填充额度恰好等于一列所需非零数时不得提前拒绝或丢弃非零");
      ++cases;
    }
    {
      const Fixture f{{0, 2, 4}, {0, 1, 0, 1}, {1e308, -1e308, 1e308, 1e308}, {0, 0}, {0, 0},
          {1, 1}, {1, 1}, {true, true}};
      const auto r = solver::v79_basis::recover(f.input(), limits, {});
      require(!r.candidate_available && r.status == "selection_update_nonfinite" &&
          r.stats.selection_pivots == 1 && r.stats.lu_factor_calls == 0 &&
          std::isfinite(r.stats.selection_threshold), "原数据和范数有限，但消元差溢出必须拒绝");
      ++cases;
    }
    {
      const Fixture f{{0, 2, 4}, {0, 1, 0, 1}, {1, 1e-200, 1e-200, 1}, {0, 0}, {0, 0},
          {1, 1}, {1, 1}, {true, true}};
      const auto r = solver::v79_basis::recover(f.input(), limits, {});
      require(!r.candidate_available && r.status == "selection_product_underflow" &&
          r.stats.selection_pivots == 1 && r.stats.lu_factor_calls == 0,
          "非零消元乘积归零不得静默视为零填充");
      ++cases;
    }
    {
      const double tiny = std::numeric_limits<double>::denorm_min();
      const Fixture f{{0, 1, 3}, {0, 0, 1}, {1, tiny, 1}, {-1, -1}, {1, 1},
          {1, 1}, {1, 1}, {true, true}};
      const auto r = solver::v79_basis::recover(f.input(), limits, {});
      check_equations(f, r);
      require(r.stats.l_nonzeros == 1, "可表示的非零subnormal填充应保留");
      ++cases;
    }
    {
      const Fixture f{{0, 2, 4, 6}, {0, 1, 0, 2, 1, 2}, {1, 1, 1, 1, 1, 1}, {-2, -2, -2},
          {3, 4, 5}, {1, 1, 1}, {1, 1, 1}, {true, true, true}};
      const auto r = solver::v79_basis::recover(f.input(), limits, {});
      check_equations(f, r);
      require(r.stats.pivot_columns == std::vector<Index>({0, 1, 2}) &&
          r.stats.selected_rows == std::vector<Index>({0, 1, 2}) && r.stats.l_nonzeros == 2,
          "新填充必须参与主元选择，同幅值按原变量号选择而非touch先后");
      close(r.x[0], 1, "完整填充恢复第一变量"); close(r.x[1], 2, "完整填充恢复第二变量");
      close(r.x[2], 3, "完整填充恢复第三变量");
      ++cases;
    }
    {
      const Fixture f{{0}, {}, {}, {}, {2}, {1}, {1}, {true}};
      const auto r = solver::v79_basis::recover(f.input(), limits, {});
      check_equations(f, r);
      require(r.x.empty() && r.stats.qr_factor_calls == 0 && r.stats.lu_factor_calls == 0,
          "零变量模型具有不分解的明确候选语义");
      require(!r.repair.candidate_available && r.repair.status == "not_started" &&
          r.repair.stats.attempts == 0, "零变量早返回不伪造修复尝试");
      std::ostringstream serialized;
      solver::v79_basis::write_diagnostics(serialized, r);
      require(serialized.str().find("\"candidate_available\":true") != std::string::npos &&
          serialized.str().find("\"selected_rows\":[]") != std::string::npos, "诊断必须记录候选与行映射");
      ++cases;
    }
    std::cout << "{\"passed\":true,\"cases\":" << cases << ",\"public_lp_runs\":0}\n";
    return 0;
  } catch (const std::exception& error) {
    std::cerr << "基恢复隔离自测失败：" << error.what() << '\n';
    return 1;
  }
}

v79-basis-instrumentation.py.source:
"""在冻结 v66 副本接入有限逆更新链，原守卫及完整候选事务保持。"""
import hashlib
from pathlib import Path
import zipfile


LOG = r'''
// 额外恢复单独记账；原内点分解和迭代计数保持原有定义。
struct V79BasisRunLog {
  bool enabled = false, attempted = false, accepted = false;
  const char* stage = "not_attempted";
  double attempt_seconds = 0, verification_seconds = 0;
  bool evaluated = false, primal_valid = false, primal_feasible = false;
  bool dual_feasible = false, gap_satisfied = false, numerically_optimal = false;
  std::optional<double> max_row_violation, max_bound_violation, max_dual_residual, objective_gap;
  ::solver::v79_basis::Result recovery;
  V79BasisRunLog() {
    const auto* value = std::getenv("SOLVER_V79_BASIS_RECOVERY");
    enabled = value && value[0] == '1' && value[1] == '\0';
  }
  ~V79BasisRunLog() noexcept {
    const auto& s = recovery.stats;
    std::fprintf(stderr, "V79_BASIS {\"schema\":1,\"enabled\":%s,\"attempted\":%s,"
        "\"accepted\":%s,\"stage\":\"%s\",\"candidate_available\":%s,"
        "\"attempt_seconds\":%.17g,\"verification_seconds\":%.17g,"
        "\"recovery_status\":\"%s\",\"stats\":{"
        "\"n\":%lld,\"m\":%lld,\"input_nonzeros\":%lld,\"rank\":%lld,"
        "\"qr_q_nonzeros\":%lld,\"qr_r_nonzeros\":%lld,"
        "\"lu_l_nonzeros\":%lld,\"lu_u_nonzeros\":%lld,\"budget_checks\":%lld,"
        "\"qr_analyze_calls\":%lld,\"qr_factor_calls\":%lld,"
        "\"lu_analyze_calls\":%lld,\"lu_factor_calls\":%lld,"
        "\"primal_solves\":%lld,\"dual_solves\":%lld,\"slack_matvecs\":%lld,"
        "\"selection_candidates\":%lld,\"selection_pivots\":%lld,\"selection_rejected\":%lld,"
        "\"work_units\":%lld,\"l_nonzeros\":%lld,\"pivot_columns_count\":%llu,"
        "\"ordered_rows_count\":%llu,\"qr_columns_permutation_count\":%llu,"
        "\"selected_rows_count\":%llu,\"qr_default_threshold\":",
        enabled ? "true" : "false", attempted ? "true" : "false", accepted ? "true" : "false",
        stage, recovery.candidate_available ? "true" : "false", attempt_seconds, verification_seconds,
        recovery.status.c_str(), static_cast<long long>(s.n), static_cast<long long>(s.m),
        static_cast<long long>(s.input_nonzeros), static_cast<long long>(s.rank),
        static_cast<long long>(s.qr_q_nonzeros), static_cast<long long>(s.qr_r_nonzeros),
        static_cast<long long>(s.lu_l_nonzeros), static_cast<long long>(s.lu_u_nonzeros),
        static_cast<long long>(s.budget_checks), static_cast<long long>(s.qr_analyze_calls),
        static_cast<long long>(s.qr_factor_calls), static_cast<long long>(s.lu_analyze_calls),
        static_cast<long long>(s.lu_factor_calls), static_cast<long long>(s.primal_solves),
        static_cast<long long>(s.dual_solves), static_cast<long long>(s.slack_matvecs),
        static_cast<long long>(s.selection_candidates), static_cast<long long>(s.selection_pivots),
        static_cast<long long>(s.selection_rejected), static_cast<long long>(s.work_units),
        static_cast<long long>(s.l_nonzeros), static_cast<unsigned long long>(s.pivot_columns.size()),
        static_cast<unsigned long long>(s.ordered_rows.size()),
        static_cast<unsigned long long>(s.qr_columns_permutation.size()),
        static_cast<unsigned long long>(s.selected_rows.size()));
    const auto number = [](std::optional<double> value) {
      if (value && std::isfinite(*value)) std::fprintf(stderr, "%.17g", *value);
      else std::fputs("null", stderr);
    };
    number(s.qr_default_threshold);
    std::fputs(",\"min_abs_pivot\":", stderr); number(s.min_abs_pivot);
    std::fputs(",\"selection_threshold\":", stderr); number(s.selection_threshold);
    std::fputs("},\"repair\":{", stderr);
    const auto& repair = recovery.repair;
    const auto& r = repair.stats;
    std::fprintf(stderr, "\"status\":\"%s\",\"candidate_available\":%s,\"stats\":{\"phase\":\"%s\"",
        repair.status.c_str(), repair.candidate_available ? "true" : "false", r.phase.c_str());
    const auto count = [](const char* name, std::int64_t value) {
      std::fprintf(stderr, ",\"%s\":%lld", name, static_cast<long long>(value));
    };
    count("attempts", r.attempts); count("iterations", r.iterations);
    count("phase1_iterations", r.phase1_iterations); count("phase2_iterations", r.phase2_iterations);
    count("pivots", r.pivots); count("zero_steps", r.zero_steps);
    count("work_units", r.work_units); count("budget_checks", r.budget_checks);
    count("lu_analyze_calls", r.lu_analyze_calls); count("lu_factor_calls", r.lu_factor_calls);
    count("factor_nonzeros", r.factor_nonzeros); count("last_factor_nonzeros", r.last_factor_nonzeros);
    count("primal_solves", r.primal_solves);
    count("dual_solves", r.dual_solves); count("direction_solves", r.direction_solves);
    count("slack_matvecs", r.slack_matvecs); count("direction_matvecs", r.direction_matvecs);
    count("pricing_matvecs", r.pricing_matvecs); count("roundoff_rows", r.roundoff_rows);
    count("final_selected_rows_count", static_cast<std::int64_t>(r.final_selected_rows.size()));
    std::fputs(",\"initial_phi\":", stderr); number(r.initial_phi);
    std::fputs(",\"final_phi\":", stderr); number(r.final_phi);
    std::fputs(",\"initial_max_violation\":", stderr); number(r.initial_max_violation);
    std::fputs(",\"final_max_violation\":", stderr); number(r.final_max_violation);
    std::fputs(",\"max_roundoff_bound\":", stderr); number(r.max_roundoff_bound);
    std::fputs(",\"last_right_derivative\":", stderr); number(r.last_right_derivative);
    std::fputs(",\"last_step\":", stderr); number(r.last_step);
    std::fputs(",\"max_selected_residual\":", stderr); number(r.max_selected_residual);
    std::fputs(",\"max_direction_residual\":", stderr); number(r.max_direction_residual);
    std::fputs(",\"last_point_error\":", stderr); number(r.last_point_error);
    std::fputs(",\"last_point_bound\":", stderr); number(r.last_point_bound);
    // 两个守卫快照分别对应原点和临时修正点，逐行尺度不能混用跨行最大值。
    std::fputs(",\"initial_guard\":", stderr);
    ::solver::v79_basis_repair::write_guard_diagnostics(stderr, r.initial_guard);
    std::fputs(",\"refined_guard\":", stderr);
    ::solver::v79_basis_repair::write_guard_diagnostics(stderr, r.refined_guard);
    std::fputs(",\"initial_refinement\":", stderr);
    ::solver::v79_basis_repair::write_refinement_diagnostics(stderr, r.initial_refinement);
    // 累计正向系统工作和最后一次右端的守卫快照由同一内核输出。
    std::fputs(",\"direction_forward\":", stderr);
    ::solver::v79_basis_repair::write_forward_diagnostics(stderr, r.direction_forward);
    std::fputs(",\"rebuild_forward\":", stderr);
    ::solver::v79_basis_repair::write_forward_diagnostics(stderr, r.rebuild_forward);
    std::fputs(",\"phase1_transition\":", stderr);
    ::solver::v79_basis_repair::write_transition_diagnostics(stderr, r.phase1_transition);
    std::fputs(",\"history\":", stderr);
    ::solver::v79_basis_repair::write_history_diagnostics(stderr, r.history);
    std::fputs(",\"search\":", stderr);
    ::solver::v79_basis_repair::write_search_diagnostics(stderr, r.search);
    std::fputs(",\"eta\":", stderr);
    ::solver::v79_basis_repair::write_eta_diagnostics(stderr, r.eta);
    std::fputs("}},\"trial_verification\":", stderr);
    if (!evaluated) std::fputs("null", stderr);
    else {
      std::fprintf(stderr, "{\"primal_valid\":%s,\"primal_feasible\":%s,\"dual_feasible\":%s,"
          "\"gap_satisfied\":%s,\"numerically_optimal\":%s,\"max_row_violation\":",
          primal_valid ? "true" : "false", primal_feasible ? "true" : "false",
          dual_feasible ? "true" : "false", gap_satisfied ? "true" : "false",
          numerically_optimal ? "true" : "false");
      number(max_row_violation);
      std::fputs(",\"max_bound_violation\":", stderr); number(max_bound_violation);
      std::fputs(",\"max_dual_residual\":", stderr); number(max_dual_residual);
      std::fputs(",\"objective_gap\":", stderr); number(objective_gap);
      std::fputs("}", stderr);
    }
    std::fputs(",\"additional_work_in_legacy_ipm_counts\":false,\"work_in_total_seconds\":true,"
        "\"marker_in_total_seconds\":false}\n", stderr);
  }
};

'''


RECOVERY = r'''  } catch (const NumericalFailure&) {
    if (!v79_log.enabled) throw;
    v79_log.attempted = true;
    v79_log.stage = "recovering";
    const auto v79_start = Clock::now();
    try {
      check_budget(options, start);
      ::solver::v79_basis::Limits v79_limits;
      v79_limits.max_input_nonzeros = 8000000;
      v79_limits.max_factor_nonzeros = 32000000;
      v79_limits.max_dimension = 1000000;
      v79_limits.max_selection_work = 1000000000;
      v79_limits.max_repair_pivots = 256;
      v79_limits.max_repair_work = 200000000;
      v79_limits.max_repair_factor_nonzeros = 64000000;
      v79_limits.max_eta_updates = 8;
      const ::solver::v79_basis::Input v79_input{model.starts, model.rows, model.values,
          model.costs, model.rhs, point.s, point.z, model.inequality};
      ::solver::v79_basis::recover(v79_input, v79_limits,
          [&] { check_budget(options, start); }, v79_log.recovery);
      if (v79_log.recovery.candidate_available) {
        v79_log.stage = "verifying";
        Point v79_point{std::move(v79_log.recovery.x), std::move(v79_log.recovery.s),
            std::move(v79_log.recovery.z)};
        // 临时副本隔离失败候选，只把实际发生的终验成本累加回原结果。
        SolveResult v79_trial = result;
        // 强制副本保留本次候选的检查，避免较差候选的诊断仍引用旧点。
        v79_trial.has_solution = false;
        const double v79_previous_verification = result.verification_seconds;
        bool v79_valid = false;
        try {
          v79_valid = assess(model, v79_point, options, start, v79_trial);
          v79_log.evaluated = true;
          v79_log.primal_valid = v79_trial.verification.valid_input;
          v79_log.primal_feasible = v79_trial.verification.feasible;
          v79_log.max_row_violation = v79_trial.verification.max_row_violation;
          v79_log.max_bound_violation = v79_trial.verification.max_bound_violation;
          if (v79_trial.lp_optimality) {
            v79_log.dual_feasible = v79_trial.lp_optimality->dual_feasible;
            v79_log.gap_satisfied = v79_trial.lp_optimality->gap_satisfied;
            v79_log.numerically_optimal = v79_trial.lp_optimality->numerically_optimal;
            v79_log.max_dual_residual = v79_trial.lp_optimality->max_dual_residual;
            v79_log.objective_gap = v79_trial.lp_optimality->objective_gap;
          }
        } catch (...) {
          result.verification_seconds = v79_trial.verification_seconds;
          v79_log.verification_seconds = v79_trial.verification_seconds - v79_previous_verification;
          throw;
        }
        result.verification_seconds = v79_trial.verification_seconds;
        v79_log.verification_seconds = v79_trial.verification_seconds - v79_previous_verification;
        check_budget(options, start);
        if (v79_valid) {
          result = std::move(v79_trial);
          v79_log.accepted = true;
          v79_log.stage = "accepted";
          v79_log.attempt_seconds = elapsed(v79_start);
          return;
        }
        v79_log.stage = "original_verification_rejected";
      } else {
        v79_log.stage = "candidate_unavailable";
      }
    } catch (const BudgetExpired&) {
      v79_log.stage = "time_limit";
      v79_log.attempt_seconds = elapsed(v79_start);
      throw;
    } catch (const std::exception&) {
      v79_log.stage = "recovery_exception";
    }
    v79_log.attempt_seconds = elapsed(v79_start);
    // 恢复没有通过时，保留原数值异常和进入恢复前的最佳点。
    throw;
  }
'''


def changes():
    signature = ('void run_homogeneous_ipm(const ConeModel& model, const SolveOptions& options,\n'
                 '    Clock::time_point start, SolveResult& result) {\n')
    loop = ('  const bool scaled_direction = options.ipm.linear_accuracy == "homogeneous_scaled";\n'
            '  for (std::int64_t iteration = 1; iteration <= options.ipm.max_iterations; ++iteration) {\n')
    ending = ('    if (iteration == options.ipm.max_iterations) break;\n'
              '  }\n}\n\nvoid validate_options(const SolveOptions& options) {\n')
    solve = ('SolveResult solve_ipm(const Model& model, const SolveOptions& options) {\n'
             '  const auto start = Clock::now();\n')
    return [
        ('#include <vector>\n', '#include <vector>\n#include <cstdio>\n#include <cstdlib>\n'
         '#include "v79-basis-recovery.hpp"\n'),
        (signature, LOG + signature.replace('SolveResult& result)', 'SolveResult& result, V79BasisRunLog& v79_log)')),
        (loop, loop.replace('  for (', '  try {\n  for (', 1)),
        (ending, '    if (iteration == options.ipm.max_iterations) break;\n  }\n' + RECOVERY +
         '}\n\nvoid validate_options(const SolveOptions& options) {\n'),
        (solve, solve + '  V79BasisRunLog v79_log;\n'),
        ('        run_homogeneous_ipm(working, options, start, result);\n',
         '        run_homogeneous_ipm(working, options, start, result, v79_log);\n'),
    ]


def transform(source):
    source = source.replace('\r\n', '\n')
    if 'v79_basis' in source or 'v79-basis-recovery' in source or 'V79BasisRunLog' in source:
        raise ValueError('输入已有 v79 候选插桩')
    original = source
    applied, anchors = [], []
    for number, (anchor, replacement) in enumerate(changes()):
        count = source.count(anchor)
        if count != 1:
            raise ValueError(f'插桩锚点 {number} 必须唯一，实际 {count} 次')
        anchors.append({'index': number, 'source_line': original[:original.index(anchor)].count('\n') + 1,
                        'anchor_sha256': hashlib.sha256(anchor.encode()).hexdigest(),
                        'replacement_sha256': hashlib.sha256(replacement.encode()).hexdigest()})
        source = source.replace(anchor, replacement, 1)
        applied.append((anchor, replacement))
    restored = source
    for anchor, replacement in reversed(applied):
        if restored.count(replacement) != 1:
            raise ValueError('逆变换锚点不唯一')
        restored = restored.replace(replacement, anchor, 1)
    if restored != original:
        raise ValueError('逆变换没有还原原始程序')
    return source, anchors


def self_check(source=None):
    if source is None:
        with zipfile.ZipFile(Path(__file__).with_name('ipm-v66-source.zip')) as archive:
            source = archive.read('src/ipm.cpp').decode('utf-8')
    transformed, anchors = transform(source)
    try:
        transform(transformed)
    except ValueError:
        pass
    else:
        raise AssertionError('重复插桩未拒绝')
    function = transformed[transformed.index('void run_homogeneous_ipm('):transformed.index('void validate_options(')]
    assert function.index('initialize(model, point, factor') < function.index('  try {')
    assert function.count('::solver::v79_basis::recover(') == 1
    assert function.count('catch (const NumericalFailure&)') == 1
    assert function.index('check_budget(options, start);\n        if (v79_valid)') < function.index('result = std::move(v79_trial)')
    selection_fields = ('selection_candidates', 'selection_pivots', 'selection_rejected', 'work_units',
                        'l_nonzeros', 'min_abs_pivot', 'selection_threshold', 'pivot_columns')
    assert all('s.' + field in LOG for field in selection_fields)
    assert 'v79_limits.max_selection_work = 1000000000;' in function
    assert 'v79_limits.max_repair_pivots = 256;' in function
    assert 'v79_limits.max_repair_work = 200000000;' in function
    assert 'v79_limits.max_repair_factor_nonzeros = 64000000;' in function
    assert 'v79_limits.max_eta_updates = 8;' in function
    repair_fields = ('attempts', 'iterations', 'phase1_iterations', 'phase2_iterations', 'pivots',
                     'zero_steps', 'work_units', 'budget_checks', 'lu_analyze_calls', 'lu_factor_calls',
                     'factor_nonzeros', 'last_factor_nonzeros', 'primal_solves', 'dual_solves', 'direction_solves', 'slack_matvecs',
                     'direction_matvecs', 'pricing_matvecs', 'roundoff_rows', 'final_selected_rows',
                     'initial_phi', 'final_phi', 'initial_max_violation', 'final_max_violation',
                     'max_roundoff_bound', 'last_right_derivative', 'last_step',
                     'max_selected_residual', 'max_direction_residual', 'last_point_error', 'last_point_bound')
    assert all('r.' + field in LOG for field in repair_fields)
    guard_fields = ('initial_guard', 'refined_guard', 'initial_refinement')
    assert all('r.' + field in LOG for field in guard_fields)
    assert LOG.count('::solver::v79_basis_repair::write_guard_diagnostics(stderr,') == 2
    assert LOG.count('::solver::v79_basis_repair::write_refinement_diagnostics(stderr,') == 1
    forward_fields = ('direction_forward', 'rebuild_forward')
    assert all('r.' + field in LOG for field in forward_fields)
    assert LOG.count('::solver::v79_basis_repair::write_forward_diagnostics(stderr,') == 2
    transition_fields = ('phase1_transition', 'history')
    assert all('r.' + field in LOG for field in transition_fields)
    assert LOG.count('::solver::v79_basis_repair::write_transition_diagnostics(stderr,') == 1
    assert LOG.count('::solver::v79_basis_repair::write_history_diagnostics(stderr,') == 1
    assert 'r.search' in LOG
    assert LOG.count('::solver::v79_basis_repair::write_search_diagnostics(stderr,') == 1
    assert 'r.eta' in LOG
    assert LOG.count('::solver::v79_basis_repair::write_eta_diagnostics(stderr,') == 1
    return {'passed': True, 'anchor_count': len(anchors), 'reversible': True, 'duplicate_rejected': True,
            'initialization_outside_recovery': True, 'single_recovery_site': True,
            'selection_diagnostic_fields': list(selection_fields), 'selection_work_limit': 1000000000,
            'repair_diagnostic_fields': list(repair_fields), 'repair_pivot_limit': 256,
            'repair_work_limit': 200000000, 'repair_cumulative_factor_limit': 64000000,
            'single_factor_limit': 32000000,
            'eta_chain_limit': 8,
            'guard_diagnostic_objects': list(guard_fields),
            'forward_diagnostic_objects': list(forward_fields),
            'transition_diagnostic_objects': list(transition_fields),
            'search_diagnostic_object': 'search',
            'eta_diagnostic_object': 'eta',
            'final_budget_before_commit': True, 'solver_runs': 0,
            'original_normalized_sha256': hashlib.sha256(source.replace('\r\n', '\n').encode()).hexdigest(),
            'transformed_sha256': hashlib.sha256(transformed.encode()).hexdigest()}

